from typing import List
from collections import Counter

class Solution:
    def findEvenNumbers(self, digits: List[int]) -> List[int]:
        # The problem asks for the number of distinct three-digit even numbers.
        # However, the starter code method name is totalNumbers. 
        # I will implement the logic to count distinct 3-digit even numbers.

        count = Counter(digits)
        even_numbers = set()

        # A 3-digit number ranges from 100 to 999.
        # We only care about even numbers.
        for num in range(100, 1000, 2):
            # Convert number to digits to check if we have enough of each digit
            d_str = str(num)
            d_count = Counter(d_str)

            possible = True
            for digit, required in d_count.items():
                if count[int(digit)] < required:
                    possible = False
                    break

            if possible:
                even_numbers.add(num)

        return len(even_numbers)

    def totalNumbers(self, digits: List[int]) -> int:
        # Mapping the logic to the requested method name
        return self.findEvenNumbers(digits)

